<h2>Check touch target size and spacing</h2><p class="lead">Compare a target's CSS pixel dimensions with the WCAG 2.2 24 × 24 CSS px minimum or a simplified same-size spacing condition.</p>
<div class="form-grid"><div class="field"><label for="w">Target width (CSS px)</label><input id="w" type="number" min="0" step="any" value="44"></div><div class="field"><label for="h">Target height (CSS px)</label><input id="h" type="number" min="0" step="any" value="44"></div><div class="field"><label for="gapX">Horizontal gap to same-size neighbor (px)</label><input id="gapX" type="number" min="0" step="any" value="8"></div><div class="field"><label for="gapY">Vertical gap to same-size neighbor (px)</label><input id="gapY" type="number" min="0" step="any" value="8"></div></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Direct 24 × 24 test</span><strong id="direct">—</strong></div><div class="metric"><span>Horizontal center spacing</span><strong id="hx">—</strong></div><div class="metric"><span>Vertical center spacing</span><strong id="vy">—</strong></div><div class="metric"><span>Simplified result</span><strong id="result">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div>
<script>
(()=>{const $=id=>document.getElementById(id);function go(){const w=parseFloat($('w').value),h=parseFloat($('h').value),gx=parseFloat($('gapX').value),gy=parseFloat($('gapY').value);if(!(w>0&&h>0&&gx>=0&&gy>=0)){$('direct').textContent=$('hx').textContent=$('vy').textContent=$('result').textContent='—';$('note').textContent='Enter positive target dimensions and non-negative gaps.';$('note').className='helper danger';return}const direct=w>=24&&h>=24,hx=w+gx,vy=h+gy,space=hx>=24&&vy>=24;$('direct').textContent=direct?'Pass':'Needs exception/spacing review';$('hx').textContent=hx.toFixed(1)+' px';$('vy').textContent=vy.toFixed(1)+' px';$('result').textContent=direct||space?'Potential pass':'Likely too small/close';$('note').textContent=direct?'The target itself is at least 24 × 24 CSS px.':'WCAG 2.2 also permits certain spacing and specific exceptions. This simplified center-spacing check assumes same-sized neighboring targets and cannot prove conformance.';$('note').className='helper'+(direct||space?'':' danger')}['w','h','gapX','gapY'].forEach(id=>$(id).addEventListener('input',go));go()})();
</script>
